  originalFactIndexes.forEach(function(index){if(!translatedBodyBlocks[index]||!factMarker.test(translatedBodyBlocks[index]))missing.push(lang.toUpperCase()+': كل بطاقة معرفة يجب أن تبدأ بعلامة مترجمة في موضع الفقرة نفسه.');});
  var coverTranslation=cover&&cover.i18n&&cover.i18n[lang];
  if(!coverTranslation||!String(coverTranslation.alt||'').trim()||!String(coverTranslation.caption||'').trim()||!String(coverTranslation.source_name||'').trim()||!String(coverTranslation.rights||'').trim())missing.push(lang.toUpperCase()+': ترجمة الوصف والتعليق واسم المصدر وحقوق الغلاف مطلوبة');else if(/[؀-ۿ]/.test(String(coverTranslation.alt)+' '+String(coverTranslation.caption)+' '+String(coverTranslation.source_name)+' '+String(coverTranslation.rights)))missing.push(lang.toUpperCase()+': بيانات الغلاف المترجمة ما زالت تحتوي نصًا عربيًا.');
  ['title','subtitle','karma_text','body'].forEach(function(k){if(!String(t[k]||'').trim())missing.push(lang.toUpperCase()+': ناقص '+({title:'العنوان',subtitle:'النبذة',karma_text:'نص كارما',body:'نص الراوي'}[k]))});['student_name','grade','title','subtitle','karma_text','body','history_note','images_note'].forEach(function(k){if(typeof t[k]==='string'&&/[؀-ۿ]/.test(t[k]))missing.push(lang.toUpperCase()+': حقل '+k+' ما زال يحتوي نصًا عربيًا بدل الترجمة المطلوبة.')});
  if(d.history_note&&!String(t.history_note||'').trim())missing.push(lang.toUpperCase()+': ترجمة السياق التاريخي ناقصة');
  if(d.images_note&&!String(t.images_note||'').trim())missing.push(lang.toUpperCase()+': ترجمة ملاحظات الصور وحقوقها ناقصة');
  if(paragraphs(d.body).length!==paragraphs(t.body).length)missing.push(lang.toUpperCase()+': عدد فقرات الراوي لا يطابق الأصل؛ لا يمكن ربط الترجمة فقرة بفقرة.');
