  LANGS.forEach(function(lang){var t=item&&item.i18n&&item.i18n[lang];if(!t||!String(t.q||'').trim()||!Array.isArray(t.o)||!item.o||t.o.length!==item.o.length||t.o.some(function(v){return !String(v||'').trim()})||!String(t.e||'').trim())missing.push('السؤال '+(i+1)+': ترجمة '+lang.toUpperCase()+' غير مكتملة');else if(/[؀-ۿ]/.test(String(t.q)+' '+String(t.e)+' '+t.o.join(' ')))missing.push('السؤال '+(i+1)+': ترجمة '+lang.toUpperCase()+' ما زالت تحتوي نصًا عربيًا في السؤال أو الاختيارات أو التفسير')});
